import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {get} from './connection.js';
import * as companies from '../../../src/main/db/repos/companies.js';
import * as gmao from '../../../src/main/db/repos/gmao.js';
import * as ops from '../../../src/main/db/repos/gmaoOperations.js';
import * as billing from '../../../src/main/db/repos/companyBilling.js';
import * as blobs from '../../../src/main/db/blobs.js';
import {makeCharter} from '../../../src/services/company/charter.js';
const db=get().db, company='billing-test',other='billing-other';
for(const id of [company,other]){companies.save({...makeCharter({name:id,mission:'Isolated billing'}),id,status:'paused'});gmao.bootstrap(id);}
const client=ops.saveClient(company,{name:'Client A'}),foreign=ops.saveClient(other,{name:'Private'});
const contract=ops.saveServiceContract(company,{name:'Monthly maintenance',clientId:client.id,vatRate:20});
const profile=billing.saveContractProfile(company,{name:'Validated public contract',serviceContractId:contract.id,issuer:{name:'Contractor',registration:'12345678900011'},recipient:{name:'Client A',registration:'11000201100044',serviceCode:'D04114W972'},channel:'chorus',legalCommitment:'1234567890',cadence:'monthly',validatedBy:'Owner',evidenceReference:'CCAP approved'});
const base={clientId:client.id,profileId:profile.id,kind:'forfait',periodStart:Date.UTC(2026,8,1),periodEnd:Date.UTC(2026,8,30),issuedAt:Date.UTC(2026,9,1),dueAt:Date.UTC(2026,9,31),admissionReference:'Monthly acceptance',lines:[{description:'Contract services',quantity:1,unitCents:20000,vatRate:20,admittedCents:20000}]};
assert.throws(()=>billing.saveInvoice(company,{...base,clientId:foreign.id}),/Référence/);
let invoice=billing.saveInvoice(company,base);
assert.equal(invoice.totalCents,24000);assert.equal(invoice.status,'draft');
assert.throws(()=>billing.saveInvoice(company,{...invoice,revision:0}),/changé/);
invoice=billing.saveInvoice(company,{...invoice,lines:[{...base.lines[0],unitCents:25000,admittedCents:25000}]});
assert.equal(invoice.totalCents,30000,'edits always recalculate TTC');
assert.throws(()=>billing.transitionInvoice(company,invoice.id,{status:'submitted',revision:invoice.revision,confirmed:true}),/Transition/);
invoice=billing.transitionInvoice(company,invoice.id,{status:'validated',revision:invoice.revision,confirmed:true,recordedBy:'Owner'});
assert.match(invoice.number,/BZF-2026-/);assert.equal(invoice.profileSnapshot.legalCommitment,'1234567890');
assert.throws(()=>billing.saveInvoice(company,invoice),/brouillon/);
const duplicate=billing.saveInvoice(company,base);
assert.throws(()=>billing.transitionInvoice(company,duplicate.id,{status:'validated',revision:duplicate.revision,confirmed:true,recordedBy:'Owner'}),/période/);
assert.throws(()=>billing.transitionInvoice(company,invoice.id,{status:'submitted',revision:invoice.revision,confirmed:true,reference:'CH1',recordedBy:'Owner',evidenceReference:'Receipt'}),/PDF|justificatif/);
const html=billing.documentHtml(company,invoice.id),blob=blobs.write(Buffer.from('%PDF-fixture'),'pdf',{mimeType:'application/pdf',source:'billing',sourceId:company});
invoice=billing.attachDocument(company,invoice.id,{blobId:blob.id,blobExt:'pdf',filename:'invoice.pdf',version:createHash('sha256').update(html).digest('hex')});
assert.throws(()=>billing.attachDocument(company,invoice.id,{blobId:blob.id,blobExt:'pdf',version:'outdated'}),/changé/);
invoice=billing.attachEvidence(company,'invoice',invoice.id,{revision:invoice.revision,filename:'receipt.txt',base64:Buffer.from('Verified external receipt').toString('base64')});
const proof={attachmentId:invoice.attachments[0].id,confirmed:true,recordedBy:'Owner',reference:'CH-1',evidenceReference:'Stored Chorus receipt'};
invoice=billing.transitionInvoice(company,invoice.id,{...proof,status:'submitted',revision:invoice.revision});
assert.equal(invoice.status,'submitted');
assert.throws(()=>billing.recordPayment(company,invoice.id,{...proof,revision:invoice.revision,amountCents:100}),/acceptation/);
invoice=billing.transitionInvoice(company,invoice.id,{...proof,reference:'CH-accepted',status:'accepted',revision:invoice.revision});
invoice=billing.recordPayment(company,invoice.id,{...proof,reference:'BANK-1',revision:invoice.revision,amountCents:10000});
assert.equal(invoice.status,'accepted','partial payment does not claim fully paid');
assert.throws(()=>billing.recordPayment(company,invoice.id,{...proof,reference:'BANK-1',revision:invoice.revision,amountCents:10000}),/déjà/);
assert.throws(()=>billing.recordPayment(company,invoice.id,{...proof,reference:'BANK-2',revision:invoice.revision,amountCents:30000}),/dépasse/);
invoice=billing.recordPayment(company,invoice.id,{...proof,reference:'BANK-2',revision:invoice.revision,amountCents:20000});assert.equal(invoice.status,'paid');
assert.equal(billing.exportDossier(company,invoice.id).submission.mode,'manual');assert.ok(billing.exportDossier(company,invoice.id).files.some(f=>Buffer.from(f.base64,'base64').subarray(0,5).toString()==='%PDF-'));
assert.throws(()=>billing.exportDossier(other,invoice.id),/Référence/);
// Legacy arithmetic + signatory persistence use the production repositories.
const site=gmao.saveSite(company,{name:'Site',trigram:'SITE',clientId:client.id,serviceContractId:contract.id});
let wo=gmao.createWorkOrder(company,{siteId:site.id,title:'Resolved visit'});
db.prepare("UPDATE gmao_work_orders SET status='on_site',intervention_started_at=? WHERE id=?").run(Date.now()-60000,wo.id);
gmao.recordAttachmentSheet(company,wo.id,{technicianName:'Technician',workPerformed:'Completed',resolved:true});
gmao.recordServiceAcceptance(company,wo.id,{reference:'SF-1',customerSignatory:'Verified Customer'});
const sf=db.prepare("SELECT evidence FROM gmao_work_order_events WHERE work_order_id=? AND event_type='service_acceptance_received'").get(wo.id);
assert.equal(JSON.parse(sf.evidence).customerSignatory,'Verified Customer');
gmao.validateProcessStep(company,wo.id,{step:'billing_requested',confirmed:true});
let old=gmao.saveInvoice(company,{workOrderId:wo.id,subtotalCents:29000,vatRate:20});
old=gmao.saveInvoice(company,{id:old.id,subtotalCents:20000,vatRate:20});assert.equal(old.totalCents,24000);
const adopted=billing.importLegacyInvoice(company,old.id);assert.equal(adopted.number,old.invoiceNumber);assert.equal(adopted.status,'draft');
assert.equal(billing.importLegacyInvoice(company,old.id).id,adopted.id,'legacy import is idempotent');
const sub=gmao.saveSubcontractor(company,{name:'Subcontractor',registration:'12345678900022'});
let dossier=billing.saveSubcontractorDossier(company,{subcontractorId:sub.id,profileId:profile.id,operationReference:'OI-1',registration:'12345678900022',declarationType:'DC4',signatory:'Contractor',annexReferences:'DC4.pdf, insurance.pdf'});
dossier=billing.attachEvidence(company,'subcontractor',dossier.id,{revision:dossier.revision,filename:'subclic-receipt.txt',base64:Buffer.from('Verified SUBCLIC receipt').toString('base64')});
const subProof={...proof,attachmentId:dossier.attachments[0].id};
dossier=billing.transitionSubcontractorDossier(company,dossier.id,{status:'ready',revision:dossier.revision,confirmed:true,recordedBy:'Owner'});
assert.throws(()=>billing.transitionSubcontractorDossier(company,dossier.id,{status:'accepted',revision:dossier.revision,confirmed:true}),/Transition/);
dossier=billing.transitionSubcontractorDossier(company,dossier.id,{...subProof,status:'submitted',revision:dossier.revision});
assert.throws(()=>billing.transitionSubcontractorDossier(company,dossier.id,{...subProof,status:'signed',revision:dossier.revision}),/signatures/);
dossier=billing.transitionSubcontractorDossier(company,dossier.id,{...subProof,status:'signed',revision:dossier.revision,contractorSignature:'Contractor signed PDF',subcontractorSignature:'Subcontractor signed PDF'});
dossier=billing.transitionSubcontractorDossier(company,dossier.id,{...subProof,status:'conditional',reason:'Missing attachment',revision:dossier.revision});
assert.equal(dossier.status,'conditional');assert.equal(dossier.history.length,4);assert.equal(billing.exportSubcontractorDossier(company,dossier.id).mode,'manual');
assert.equal(billing.snapshot(company).invoices.length,3);
assert.equal(db.prepare('PRAGMA foreign_key_check').all().length,0);
console.log('Billing ledger: arithmetic, evidence gates, receipts, partial payments, immutable validation, duplicate periods, legacy adoption, isolation and SUBCLIC dossier passed.');

// An ordinary finance team does not need maintenance data to create a customer invoice.
const general='ordinary-finance';companies.save({...makeCharter({name:'Independent consultant',mission:'Finance'}),id:general,status:'paused'});
const customer=billing.saveCustomer(general,{name:'Small business',email:'billing@example.invalid'});
let normal=billing.saveInvoice(general,{clientId:customer.id,kind:'standalone',issuedAt:Date.now(),dueAt:Date.now()+86400000,parties:{issuer:{name:'Consultant',registration:'123456789',address:'1 street'},recipient:{name:customer.name,address:'2 street'}},lines:[{description:'Consulting',quantity:2,unitCents:5000,vatRate:20}]});
assert.equal(billing.snapshot(general).invoices[0].issues.length,0);
normal=billing.transitionInvoice(general,normal.id,{revision:normal.revision,status:'validated',confirmed:true,recordedBy:'Owner'});
assert.ok(billing.documentHtml(general,normal.id).includes('120,00'));assert.ok(!billing.documentHtml(general,normal.id).includes('Marché :'));
assert.throws(()=>billing.attachEvidence(other,'invoice',normal.id,{revision:normal.revision,filename:'proof.txt',base64:'eA=='}),/Référence/);
// A remote timeout never becomes a success or a retryable financial write.
let pending=billing.saveInvoice(company,{...base,periodStart:Date.UTC(2026,9,1),periodEnd:Date.UTC(2026,9,31)});
pending=billing.transitionInvoice(company,pending.id,{revision:pending.revision,status:'validated',confirmed:true,recordedBy:'Owner'});
const pendingHtml=billing.documentHtml(company,pending.id);
pending=billing.attachDocument(company,pending.id,{blobId:blob.id,blobExt:'pdf',filename:'invoice.pdf',version:createHash('sha256').update(pendingHtml).digest('hex')});
pending=billing.beginChorusAction(company,pending.id,{revision:pending.revision,operation:'upload',recordedBy:'Owner',confirmed:true});
const uploadAttempt=pending.chorus.attempt.id;
assert.throws(()=>billing.beginChorusAction(company,pending.id,{revision:pending.revision,operation:'upload',recordedBy:'Owner',confirmed:true}),/incertain/);
pending=billing.finishChorusAction(company,pending.id,uploadAttempt,{result:{pieceJointeId:81}});assert.equal(pending.status,'validated');assert.equal(pending.chorus.externalStatus,'INTERPRETEE_OCR');
pending=billing.beginChorusAction(company,pending.id,{revision:pending.revision,operation:'submit',recordedBy:'Owner',confirmed:true});
pending=billing.finishChorusAction(company,pending.id,pending.chorus.attempt.id,{error:'Network interrupted',outcome:'unknown'});assert.equal(pending.status,'validated');assert.equal(pending.chorus.attempt.status,'unknown');
assert.throws(()=>billing.beginChorusAction(company,pending.id,{revision:pending.revision,operation:'submit',recordedBy:'Owner',confirmed:true}),/incertain/);
pending=billing.attachEvidence(company,'invoice',pending.id,{revision:pending.revision,filename:'chorus-proof.txt',base64:Buffer.from('Verified Chorus submission #88').toString('base64')});
pending=billing.reconcileChorusAction(company,pending.id,{...proof,revision:pending.revision,attachmentId:pending.attachments.at(-1).id,resolution:'submitted',invoiceId:88});assert.equal(pending.status,'submitted');assert.equal(pending.chorus.invoiceId,88);
// SQL foreign keys and decoded dossier identities stay aligned when editing drafts.
const sub2=gmao.saveSubcontractor(company,{name:'Other contractor',registration:'12345678900033'});
let changed=billing.saveSubcontractorDossier(company,{subcontractorId:sub.id,profileId:profile.id});
changed=billing.saveSubcontractorDossier(company,{...changed,subcontractorId:sub2.id});assert.equal(changed.subcontractorId,sub2.id);assert.equal(db.prepare('SELECT subcontractor_id FROM company_billing_subcontractors WHERE id=?').get(changed.id).subcontractor_id,sub2.id);
pending=billing.beginChorusAction(company,pending.id,{revision:pending.revision,operation:'status',recordedBy:'Owner',confirmed:true});
pending=billing.finishChorusAction(company,pending.id,pending.chorus.attempt.id,{result:{codeRetour:0,idFacture:88,statutCourantCode:'MISE_EN_PAIEMENT'}});assert.equal(pending.status,'submitted','Chorus payment initiation is not proof of received funds');assert.equal(pending.chorus.externalStatus,'MISE_EN_PAIEMENT');
let submitted=billing.saveInvoice(company,{...base,periodStart:Date.UTC(2026,10,1),periodEnd:Date.UTC(2026,10,30)});
submitted=billing.transitionInvoice(company,submitted.id,{revision:submitted.revision,status:'validated',confirmed:true,recordedBy:'Owner'});
submitted=billing.attachDocument(company,submitted.id,{blobId:blob.id,blobExt:'pdf',filename:'invoice.pdf',version:createHash('sha256').update(billing.documentHtml(company,submitted.id)).digest('hex')});
submitted=billing.beginChorusAction(company,submitted.id,{revision:submitted.revision,operation:'upload',recordedBy:'Owner',confirmed:true});submitted=billing.finishChorusAction(company,submitted.id,submitted.chorus.attempt.id,{result:{pieceJointeId:82}});
submitted=billing.beginChorusAction(company,submitted.id,{revision:submitted.revision,operation:'submit',recordedBy:'Owner',confirmed:true});submitted=billing.finishChorusAction(company,submitted.id,submitted.chorus.attempt.id,{result:{codeRetour:0,identifiantFactureCPP:89,statutFacture:'DEPOSEE'}});assert.equal(submitted.status,'submitted');assert.equal(submitted.submittedReceipt.source,'chorus_api');assert.ok(blobs.exists(submitted.submittedReceipt.blobId,'json'));
// An invoice covered fully by a documented advance has a zero balance, not an impossible minimum payment.
let covered=billing.saveInvoice(general,{clientId:customer.id,kind:'standalone',issuedAt:Date.now(),dueAt:Date.now()+86400000,parties:normal.parties,lines:[{description:'Prepaid service',quantity:1,unitCents:10000,vatRate:20}],advanceAppliedCents:12000,advanceReference:'Verified bank advance'});
covered=billing.transitionInvoice(general,covered.id,{revision:covered.revision,status:'validated',confirmed:true,recordedBy:'Owner'});
covered=billing.attachDocument(general,covered.id,{blobId:blob.id,blobExt:'pdf',filename:'prepaid.pdf',version:createHash('sha256').update(billing.documentHtml(general,covered.id)).digest('hex')});
covered=billing.attachEvidence(general,'invoice',covered.id,{revision:covered.revision,filename:'advance.txt',base64:Buffer.from('Advance paid and invoice accepted').toString('base64')});const coveredProof={...proof,attachmentId:covered.attachments[0].id};
for(const status of ['submitted','accepted'])covered=billing.transitionInvoice(general,covered.id,{...coveredProof,revision:covered.revision,status});
covered=billing.recordPayment(general,covered.id,{...coveredProof,revision:covered.revision,amountCents:0});assert.equal(covered.status,'paid');assert.equal(covered.payments[0].amountCents,0);
